import os
from joblib import Parallel, delayed
import warnings
from common.utils import rclone
from server.storage.combined import CombinedWriter

from server.settings import OUTPUT_BASE, RCS_SOURCE_NAME


def iter_new_dates(patient, rebuild=False, skip_dates=None):
    """Fetch all the data for a single patient based on the wasabi rc+s data"""
    rcs_path = os.path.join(patient, RCS_SOURCE_NAME)
    if skip_dates is None:
        skip_dates = []
    for raw_date in rclone.list_remote(os.path.join(rcs_path)):
        clean_date = raw_date.strip()[:-1]  # Remove whitespaces and trailing slash
        out_path = os.path.join(OUTPUT_BASE, patient, f'{clean_date}.h5')
        if clean_date in skip_dates or (not rebuild and os.path.exists(out_path)):
            print(f'Skipping {clean_date}')
            continue  # Skip existing files if we're not rebuilding
        else:
            yield clean_date


def fetch_patient(patient, rebuild=False, n_jobs=1, skip_dates=None):
    """Fetch all the data for a single patient based on the wasabi rc+s data"""
    all_dates = iter_new_dates(patient, rebuild=rebuild, skip_dates=skip_dates)

    Parallel(n_jobs=n_jobs, verbose=20)([
        delayed(write_patient_date)(date, patient)
        for date in all_dates
    ])


def write_patient_date(clean_date, patient):
    print(f'Processing {clean_date}')
    try:
        date_data = CombinedWriter.date_fetch(clean_date, patient=patient, output_dir=OUTPUT_BASE, use_delays=True)
        date_data.write(overwrite=True)
    except Exception as e:
        import sys, traceback
        msg = f'{e}\n' \
              f'\n' \
              f'{traceback.format_exc()}\n' \
              f'\n' \
              f'{sys.exc_info()[2]}'
        with open(os.path.join(OUTPUT_BASE, patient, f'{clean_date}_errors.txt'), 'w') as f:
            f.write(msg)


if __name__ == "__main__":
    import argparse

    parser = argparse.ArgumentParser()
    parser.add_argument('--multi', action='store_true')
    parser.set_defaults(feature=False)
    args = parser.parse_args()
    if args.multi:
        n_jobs = 8
    else:
        n_jobs = 1
    fetch_patient('rcs07', n_jobs=n_jobs, rebuild=False,
                  skip_dates=['20211025', '20210920'])
